#include <iostream>
#include <vector>
#include <string>
using namespace std;

struct TrieNode {
    int next[26];
    bool end = false;
    TrieNode() { for (int i = 0; i < 26; i++) next[i] = -1; }
};

vector<TrieNode> trie(1);

void trieInsert(const string& word) {
    int node = 0;
    for (char ch : word) {
        if (trie[node].next[ch - 'a'] < 0) {
            trie[node].next[ch - 'a'] = (int)trie.size();
            trie.push_back(TrieNode());
        }
        node = trie[node].next[ch - 'a'];
    }
    trie[node].end = true;
}

int trieFind(const string& s) {
    int node = 0;
    for (char ch : s) {
        node = trie[node].next[ch - 'a'];
        if (node < 0) return -1;
    }
    return node;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<string> words(n);
    for (int i = 0; i < n; i++) cin >> words[i];
    long long q;
    cin >> q;
    vector<vector<string>> queries(q, vector<string>(2));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> queries[i][j];
        }
    }

    for (const string& w : words) trieInsert(w);
    for (int i = 0; i < q; i++) {
        int node = trieFind(queries[i][1]);
        bool ok = queries[i][0] == "word" ? (node >= 0 && trie[node].end) : node >= 0;
        cout << (ok ? "yes" : "no") << "\n";
    }

    return 0;
}

