import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[][] child = new int[100001][26];
    static boolean[] endMark = new boolean[100001];
    static int nodes = 1;

    static void trieInsert(String word) {
        int node = 0;
        for (char ch : word.toCharArray()) {
            if (child[node][ch - 'a'] == 0) child[node][ch - 'a'] = nodes++;
            node = child[node][ch - 'a'];
        }
        endMark[node] = true;
    }

    static int trieFind(String s) {
        int node = 0;
        for (char ch : s.toCharArray()) {
            node = child[node][ch - 'a'];
            if (node == 0) return -1;
        }
        return node;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        String[] words = new String[(int) n];
        for (int i = 0; i < words.length; i++) words[i] = next();
        long q = Long.parseLong(next());
        String[][] queries = new String[(int) q][2];
        for (int i = 0; i < queries.length; i++) {
            for (int j = 0; j < queries[i].length; j++) {
                queries[i][j] = next();
            }
        }

        for (String w : words) trieInsert(w);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            int node = trieFind(queries[i][1]);
            boolean ok = queries[i][0].equals("word") ? (node >= 0 && endMark[node]) : node >= 0;
            sb.append(ok ? "yes" : "no").append("\n");
        }
        System.out.print(sb);
    }
}
